<?php
declare(strict_types=1);
function scoreboardEnv(string $key,string $default=''):string{static $env=null;if($env===null){$env=[];foreach(is_file(__DIR__.'/.env')?file(__DIR__.'/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES):[] as $line){if(!str_starts_with(ltrim($line),'#')&&str_contains($line,'=')){[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim($v);}}}return $env[$key]??$default;}
function scoreboardDb():PDO{static $pdo=null;if($pdo)return $pdo;$pdo=new PDO('mysql:host='.scoreboardEnv('DB_HOST').';dbname='.scoreboardEnv('DB_NAME').';charset=utf8',scoreboardEnv('DB_USER'),scoreboardEnv('DB_PASS'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec('CREATE TABLE IF NOT EXISTS tbl_dashboard_settings(setting_key VARCHAR(50) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8');$pdo->exec('CREATE TABLE IF NOT EXISTS tbl_dashboard_teams(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,team_name VARCHAR(50) NOT NULL,overall_score DECIMAL(8,2) NOT NULL DEFAULT 0,team_color CHAR(7) NOT NULL DEFAULT "#0d6efd",team_logo MEDIUMTEXT NULL,display_order INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8');$pdo->exec('CREATE TABLE IF NOT EXISTS tbl_dashboard_sports(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sport_name VARCHAR(80) NOT NULL,display_order INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8');$pdo->exec('CREATE TABLE IF NOT EXISTS tbl_dashboard_sport_scores(team_id INT UNSIGNED NOT NULL,sport_id INT UNSIGNED NOT NULL,score DECIMAL(8,2) NOT NULL DEFAULT 0,PRIMARY KEY(team_id,sport_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8');$pdo->exec('ALTER TABLE tbl_dashboard_teams MODIFY overall_score DECIMAL(8,2) NOT NULL DEFAULT 0');$pdo->exec('ALTER TABLE tbl_dashboard_sport_scores MODIFY score DECIMAL(8,2) NOT NULL DEFAULT 0');try{$pdo->exec('ALTER TABLE tbl_dashboard_teams ADD COLUMN team_logo MEDIUMTEXT NULL AFTER team_color');}catch(Throwable $e){}return $pdo;}
function scoreboardData():array{$data=['title'=>'League Scoreboard','subtitle'=>'Overall Team Standings','sports'=>[],'teams'=>[]];$pdo=scoreboardDb();foreach($pdo->query('SELECT setting_key,setting_value FROM tbl_dashboard_settings') as $r)if(isset($data[$r['setting_key']]))$data[$r['setting_key']]=$r['setting_value'];$data['sports']=$pdo->query('SELECT id,sport_name name FROM tbl_dashboard_sports ORDER BY display_order,id')->fetchAll();$data['teams']=$pdo->query('SELECT id,team_name name,overall_score score,team_color color,team_logo logo FROM tbl_dashboard_teams ORDER BY display_order,id')->fetchAll();$rows=$pdo->query('SELECT team_id,sport_id,score FROM tbl_dashboard_sport_scores')->fetchAll();foreach($data['teams'] as &$team){$team['sport_scores']=[];foreach($rows as $r)if($r['team_id']==$team['id'])$team['sport_scores'][(int)$r['sport_id']]=(float)$r['score'];}unset($team);return $data;}
function saveScoreboard(array $data):void{$pdo=scoreboardDb();$pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO tbl_dashboard_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute(['title',$data['title']]);$q->execute(['subtitle',$data['subtitle']]);$pdo->exec('DELETE FROM tbl_dashboard_sport_scores');$pdo->exec('DELETE FROM tbl_dashboard_teams');$pdo->exec('DELETE FROM tbl_dashboard_sports');$sports=[];$q=$pdo->prepare('INSERT INTO tbl_dashboard_sports(sport_name,display_order) VALUES(?,?)');foreach($data['sports'] as $i=>$s){$q->execute([$s,$i]);$sports[]=$pdo->lastInsertId();}$team=$pdo->prepare('INSERT INTO tbl_dashboard_teams(team_name,overall_score,team_color,team_logo,display_order) VALUES(?,?,?,?,?)');$score=$pdo->prepare('INSERT INTO tbl_dashboard_sport_scores(team_id,sport_id,score) VALUES(?,?,?)');foreach($data['teams'] as $i=>$t){$team->execute([$t['name'],$t['score'],$t['color'],$t['logo']!==''?$t['logo']:null,$i]);$id=$pdo->lastInsertId();foreach($sports as $n=>$sport)$score->execute([$id,$sport,(float)($t['sports'][$n]??0)]);}$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}
